INSERT INTO public.domains (id, name, slug, description, icon) VALUES
  ('fundamentals', 'Cybersecurity Fundamentals', 'fundamentals', 'Core security models, CIA triad, security controls, and defense architectures.', 'Shield'),
  ('network-security', 'Networking & Network Security', 'network-security', 'Packet inspection, firewall architectures, TCP/IP, Wireshark, and Nmap.', 'Network'),
  ('soc-blue-team', 'SOC & Blue Team Operations', 'soc-blue-team', 'SIEM correlation, alert triage, incident detection, and defense in depth.', 'Activity'),
  ('red-team-pentest', 'Red Team & Penetration Testing', 'red-team-pentest', 'Adversary emulation, exploitation techniques, privilege escalation, and stealth.', 'Flame'),
  ('web-app-security', 'Web & Application Security', 'web-app-security', 'OWASP Top 10, API vulnerabilities, business logic flaws, and secure code review.', 'Globe'),
  ('dfir', 'Digital Forensics & Incident Response', 'dfir', 'Memory dumps, disk artifact extraction, timelines, and post-breach response.', 'Search'),
  ('malware-reverse-engineering', 'Malware Analysis & Reverse Engineering', 'malware-reverse-engineering', 'Static PE analysis, dynamic sandboxing, decompilation, and disassembly.', 'Cpu'),
  ('cloud-security', 'Cloud Security', 'cloud-security', 'AWS/Azure/GCP IAM policies, container isolation, and Kubernetes hardening.', 'Cloud'),
  ('osint-threat-intel', 'OSINT & Threat Intelligence', 'osint-threat-intel', 'Open-source reconnaissance, MITRE ATT&CK mapping, and threat actor profiling.', 'Target'),
  ('iot-embedded-security', 'IoT & Embedded Security', 'iot-embedded-security', 'Firmware extraction, hardware bus auditing (UART/JTAG), and embedded protocols.', 'Radio'),
  ('cryptography', 'Cryptography', 'cryptography', 'Symmetric/asymmetric algorithms, PKI, hash functions, and quantum resistance.', 'Key')
